// === Tab: mySketch ===
let _minWidth;
let _aryPoints = [];
let _numTile;
let _d;
let slider_d;
let slider_type;
let _type;
let _unitTime;

function setup() {
  createCanvas(windowWidth, windowHeight);
  _minWidth = max(width, height) * 0.8;
  colorMode(HSB, 360, 100, 100, 255);
  ellipseMode(RADIUS);
  frameRate(30);
  noFill();
  stroke(0);
  strokeJoin(ROUND);
  strokeWeight(_minWidth/300);
  strokeCap(SQUARE);
  ellipseMode(RADIUS);

  setObject();

  slider_d = createSlider(1, 50, 6, 1);//min max default step
  slider_type = createSlider(1, 3, 3, 1);//min max default step 1=in 2=out 3=inout
  slider_d.position(10, 10);
  slider_type.position(10,　40);
  textSize(15);
}

function setObject() {
  let numPoints = 16;
  let xy1Start = createVector(0, 0);
  let xy2Start = createVector(0, 0);
  _unitTime = 30;
  _numTile = 4;
  let xyShift = createVector(_minWidth / _numTile, 0);
  _aryPoints = [];
  let maxR = _minWidth / _numTile / 2 * 0.8;
  for (let i = 0; i < numPoints; i++) {
    let xy1End = p5.Vector.add(xy1Start, p5.Vector.rotate(xyShift, PI/2 * random([0, 1, 2, 3])));
    let xy2End = p5.Vector.add(xy2Start, p5.Vector.rotate(xyShift, PI/2 * random([0, 1, 2, 3])));
    let r = maxR / numPoints *(i + 1);
    _aryPoints[i] = new Points(xy1Start, xy1End, xy2Start, xy2End, r, _unitTime, xyShift);
  }
}

class Points {
  constructor(xy1Start, xy1End, xy2Start, xy2End, r, unitTime, xyShift) {
    this.xy1Start = xy1Start;
    this.xy1End = xy1End;
    this.xy2Start = xy2Start;
    this.xy2End = xy2End;
    this.r = r;
    this.unitTime = unitTime;
    this.timeNumber = 0;
    this.count = 0;
    this.xyShift = xyShift;
  }

  update() {
    let unitTime = this.unitTime;
    this.xy1Current = p5.Vector.lerp(this.xy1Start, this.xy1End, easing(unitTime, this.count, _type));
    this.xy2Current = p5.Vector.lerp(this.xy2Start, this.xy2End, easing(unitTime, this.count, _type));
    this.count++;
    if (this.count > unitTime) {
      this.count = 0;
      // this.timeNumber = (this.timeNumber + 1) % this.aryTime.length;
      this.xy1Start = this.xy1End;
      let xy1EndNew = p5.Vector.add(this.xy1End, p5.Vector.rotate(this.xyShift, PI/2 * random([0, 1, 2, 3])));
      let margin = 1.01;
      let _wG_1 = 0; while ((xy1EndNew.x > _minWidth/2 * margin || xy1EndNew.x < -_minWidth/2 * margin || xy1EndNew.y > _minWidth/2 * margin || xy1EndNew.y < -_minWidth/2 * margin) && ++_wG_1 < 20000) {

        xy1EndNew = p5.Vector.add(this.xy1End, p5.Vector.rotate(this.xyShift, PI/2 * random([0, 1, 2, 3])));
      }
      this.xy1End = xy1EndNew;
      this.xy2Start = this.xy2End;
      let xy2EndNew = p5.Vector.add(this.xy2End, p5.Vector.rotate(this.xyShift, PI/2 * random([0, 1, 2, 3])));
      let _wG_2 = 0; while ((xy2EndNew.x > _minWidth/2 * margin || xy2EndNew.x < -_minWidth/2 * margin || xy2EndNew.y > _minWidth/2 * margin || xy2EndNew.y < -_minWidth/2 * margin) && ++_wG_2 < 20000) {
        xy2EndNew = p5.Vector.add(this.xy2End, p5.Vector.rotate(this.xyShift, PI/2 * random([0, 1, 2, 3])));
      }
      this.xy2End = xy2EndNew;
      this.xy1Current = this.xy1Start;
      this.xy2Current = this.xy2Start;
    }
  }

  draw() {
    if (this.xy1Current.x == this.xy2Current.x && this.xy1Current.y == this.xy2Current.y) {
      ellipse(this.xy2Current.x, this.xy2Current.y, this.r);
    } else {
      let aryPoints = getContactLine(this.xy1Current, this.xy2Current, this.r, this.r);
      drawVertexShape(aryPoints);
    } 
  }
}

function getContactLine(xy1, xy2, r1, r2) {
  let xy_l;
  let xy_s;
  let r_l;
  let r_s;
  if (r1 > r2) {
    xy_l = xy1;
    xy_s = xy2;
    r_l = r1;
    r_s = r2;
  } else {
    xy_l = xy2;
    xy_s = xy1;
    r_l = r2;
    r_s = r1;
  }
  let d = p5.Vector.dist(xy_l, xy_s);
  let theta_l = acos((r_l - r_s) / d);
  let vec_l_s = p5.Vector.sub(xy_s, xy_l);
  let vec_radius_l = p5.Vector.rotate(vec_l_s, theta_l).setMag(r_l);
  let numAng = 64;

  let aryContactLinePoints = [];
  for (let i = 0; i < numAng + 1; i++) {
    let vec = p5.Vector.add(xy_l, vec_radius_l);
    aryContactLinePoints.push(vec);
    vec_radius_l.rotate((2*PI - theta_l * 2) / numAng);
  }
  let theta_s = PI - theta_l;
  let vec_s_l = p5.Vector.sub(xy_l, xy_s);
  let vec_radius_s = p5.Vector.rotate(vec_s_l, theta_s).setMag(r_s);
  for (let i = 0; i < numAng + 1; i++) {
    let vec = p5.Vector.add(xy_s, vec_radius_s);
    aryContactLinePoints.push(vec);
    vec_radius_s.rotate((2*PI - theta_s * 2) / numAng);
  }

  return aryContactLinePoints;
}

function drawVertexShape(aryPoints) {
  beginShape();
  for (let i = 0; i < aryPoints.length; i++) {
    vertex(aryPoints[i].x, aryPoints[i].y);
  }
  endShape(CLOSE);
}

function easing(unitTime, t, type) {
  let value;
  if (type == "in") {
    value = easeIn(unitTime, t);
  } else if (type == "out") {
    value = easeOut(unitTime, t);
  } else if (type == "inout") {
    value = easeInOut(unitTime, t);
  }

  return value;
}

function easeIn(unitTime, t) {
  let d = _d;
  let value = (t / unitTime)**d;

  return value;
}

function easeOut(unitTime, t) {
  let t2 = unitTime - t;
  let value = 1 - easeIn(unitTime, t2);

  return value;
}

function easeInOut(unitTime, t) {
  let t2;
  let value;
  if (t < unitTime / 2) {
    t2 = t * 2;
    value = easeIn(unitTime, t2) / 2;
  } else {
    t2 = t * 2 - unitTime;
    value = easeOut(unitTime, t2) / 2 + 0.5;
  }

  return value;
}

function drawLattice() {
  push();
  noFill();
  stroke(90);
  let step = _minWidth / _numTile;
  let maxLaticeShift = int((_minWidth / 2) / step);
  for (let x = -(maxLaticeShift + 0.5); x <= maxLaticeShift + 0.5; x++) {
    line(x * step, -(maxLaticeShift + 0.5) * step, x * step, (maxLaticeShift + 0.5) * step);
  }
  for (let y = -(maxLaticeShift + 0.5); y <= maxLaticeShift + 0.5; y++) {
    line(-(maxLaticeShift + 0.5) * step, y * step, (maxLaticeShift + 0.5) * step, y * step);
  }
  pop();
}

function slidebar() {
  let txt;
  if (slider_type.value() == 1) {
    _type = "in";
    txt = "ease-in";
  } else if (slider_type.value() == 2) {
    _type = "out";
    txt = "ease-out";
  } else if (slider_type.value() == 3) {
    _type = "inout";
    txt = "ease-in-out";
  }
  _d = slider_d.value();
  push();
  noStroke();
  fill(0);
  text("easing degree = "+_d, -width/2 + 150, -height/2 + 25);
  text(txt, -width/2 + 150, -height/2 + 55);
  pop();
}

function draw() {
  translate(width/2, height/2);
  background(100);

  drawLattice();

  slidebar();

  for (let i = 0; i < _aryPoints.length; i++) {
    _aryPoints[i].update();
    _aryPoints[i].draw();
  }
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
